//! Wet flexible-fiber agglomerate impact recorder.
//!
//! The executable is intentionally thin: all case setup stays in declarative
//! TOML/CSV files generated by `sweep.py`, while this recorder measures the
//! Yang/Curtis breakage observables from the running DIRT state.

use dirt_core::dirt_atom::DemAtom;
use dirt_core::dirt_bond::{BondMetrics, DemBondPlugin};
use dirt_core::dirt_fixes::FixesPlugin;
use dirt_core::dirt_granular::contact::willett2000_liquid_bridge_force;
use dirt_core::prelude::*;
use dirt_core::soil_core::BondStore;
use std::collections::HashSet;
use std::fs::{self, File};
use std::io::{BufWriter, Write as IoWrite};

const BEADS_PER_FIBER: u32 = 5;

struct ImpactRecorder {
    writer: Option<BufWriter<File>>,
    initial_contacts: Option<usize>,
    initial_bond_count: Option<usize>,
    min_contacts: usize,
    min_largest_fragment_mass_ratio: f64,
    record_every: usize,
}

impl ImpactRecorder {
    fn new() -> Self {
        Self {
            writer: None,
            initial_contacts: None,
            initial_bond_count: None,
            min_contacts: usize::MAX,
            min_largest_fragment_mass_ratio: 1.0,
            record_every: 200,
        }
    }
}

fn main() {
    let mut app = App::new();
    app.add_plugins(CorePlugins)
        .add_plugins(GranularDefaultPlugins)
        .add_plugins(FixesPlugin)
        .add_plugins(DemBondPlugin);

    app.add_resource(ImpactRecorder::new());
    app.add_update_system(
        record_breakage,
        ParticleSimScheduleSet::PostFinalIntegration,
    );
    app.start();
}

fn fiber_id(tag: u32) -> usize {
    ((tag - 1) / BEADS_PER_FIBER) as usize
}

fn find(parents: &mut [usize], x: usize) -> usize {
    if parents[x] != x {
        let root = find(parents, parents[x]);
        parents[x] = root;
    }
    parents[x]
}

fn union(parents: &mut [usize], a: usize, b: usize) {
    let ra = find(parents, a);
    let rb = find(parents, b);
    if ra != rb {
        parents[rb] = ra;
    }
}

fn record_breakage(
    atoms: Res<Atom>,
    registry: Res<AtomDataRegistry>,
    bond_metrics: Res<BondMetrics>,
    material_table: Res<MaterialTable>,
    neighbor: Res<Neighbor>,
    run_state: Res<RunState>,
    input: Res<Input>,
    mut rec: ResMut<ImpactRecorder>,
) {
    let step = run_state.total_cycle;
    if step % rec.record_every != 0 {
        return;
    }

    if rec.writer.is_none() {
        let out_dir = input
            .output_dir
            .clone()
            .unwrap_or_else(|| "examples/bench_curtis_wet_fiber_breakage".to_string());
        fs::create_dir_all(format!("{}/data", out_dir)).ok();
        let path = format!("{}/data/impact_metrics.csv", out_dir);
        let mut writer =
            BufWriter::new(File::create(&path).unwrap_or_else(|e| panic!("{}: {}", path, e)));
        writeln!(
            writer,
            "step,time,bridge_contacts,breakage_ratio,largest_fragment_mass_ratio,bond_count,bonds_broken"
        )
        .unwrap();
        println!("wet fiber impact metrics -> {}", path);
        rec.writer = Some(writer);
    }

    let nlocal = atoms.nlocal as usize;
    if nlocal == 0 {
        return;
    }
    let mut parent: Vec<usize> = (0..nlocal).collect();
    let mut bridge_contacts = 0usize;
    let mut seen_bridge_pairs: HashSet<(usize, usize)> = HashSet::new();

    let dem = registry.expect::<DemAtom>("wet_fiber_breakage_recorder");
    for (i, j) in neighbor.pairs(nlocal) {
        if j >= nlocal {
            continue;
        }
        let fi = fiber_id(atoms.tag[i]);
        let fj = fiber_id(atoms.tag[j]);
        if fi == fj {
            continue;
        }

        let mat_i = atoms.atom_type[i] as usize;
        let mat_j = atoms.atom_type[j] as usize;
        if material_table.liquid_bridge_model != "willett2000"
            || mat_i >= material_table.liquid_bridge_volume_ij.len()
            || mat_j >= material_table.liquid_bridge_volume_ij[mat_i].len()
        {
            continue;
        }
        let volume = material_table.liquid_bridge_volume_ij[mat_i][mat_j];
        let gamma = material_table.liquid_surface_tension_ij[mat_i][mat_j];
        if volume <= 0.0 || gamma <= 0.0 {
            continue;
        }

        let dx = atoms.pos[j][0] as f64 - atoms.pos[i][0] as f64;
        let dy = atoms.pos[j][1] as f64 - atoms.pos[i][1] as f64;
        let dz = atoms.pos[j][2] as f64 - atoms.pos[i][2] as f64;
        let dist = (dx * dx + dy * dy + dz * dz).sqrt();
        if dist == 0.0 {
            continue;
        }
        let sum_r = dem.radius[i] + dem.radius[j];
        let r_eff = (dem.radius[i] * dem.radius[j]) / sum_r;
        let separation = (dist - sum_r).max(0.0);
        let f_bridge = willett2000_liquid_bridge_force(
            separation,
            r_eff,
            volume,
            gamma,
            material_table.liquid_contact_angle_ij[mat_i][mat_j],
            material_table.liquid_rupture_distance_ij[mat_i][mat_j],
        );
        if f_bridge > 0.0 {
            let a = fi.min(fj);
            let b = fi.max(fj);
            if seen_bridge_pairs.insert((a, b)) {
                bridge_contacts += 1;
            }
            union(&mut parent, i, j);
        }
    }

    if let Some(bonds) = registry.get::<BondStore>() {
        for i in 0..nlocal.min(bonds.bonds.len()) {
            for b in &bonds.bonds[i] {
                if atoms.tag[i] < b.partner_tag {
                    if let Some(j) = (0..nlocal).find(|&k| atoms.tag[k] == b.partner_tag) {
                        union(&mut parent, i, j);
                    }
                }
            }
        }
    }

    let mut component_mass = vec![0.0f64; nlocal];
    for i in 0..nlocal {
        let root = find(&mut parent, i);
        component_mass[root] += atoms.mass[i];
    }
    let total_mass: f64 = (0..nlocal).map(|i| atoms.mass[i]).sum();
    let largest_ratio = if total_mass > 0.0 {
        component_mass.into_iter().fold(0.0, f64::max) / total_mass
    } else {
        0.0
    };

    let n0 = *rec.initial_contacts.get_or_insert(bridge_contacts.max(1));
    rec.min_contacts = rec.min_contacts.min(bridge_contacts);
    rec.min_largest_fragment_mass_ratio = rec.min_largest_fragment_mass_ratio.min(largest_ratio);
    let breakage_ratio = (n0 as f64 - bridge_contacts as f64) / n0 as f64;
    let inferred_bonds_broken = rec
        .initial_bond_count
        .get_or_insert(bond_metrics.bond_count)
        .saturating_sub(bond_metrics.bond_count)
        .max(bond_metrics.total_bonds_broken);

    if let Some(ref mut writer) = rec.writer {
        writeln!(
            writer,
            "{},{:.8e},{},{:.8e},{:.8e},{},{}",
            step,
            step as f64 * atoms.dt,
            bridge_contacts,
            breakage_ratio,
            largest_ratio,
            bond_metrics.bond_count,
            inferred_bonds_broken,
        )
        .ok();
    }
}
